let toastTimer,generationController,activePromptId;
function toast(message){$('toast-message').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3600);}
function navigate(page){if(!['create','workflows','library','models','tutorial'].includes(page))return;state.page=page;document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==`${page}-page`);document.querySelectorAll('.nav-item[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('breadcrumb-page').textContent=page==='library'?'My library':page[0].toUpperCase()+page.slice(1);$('sidebar-placeholder')?.remove();document.querySelector('.sidebar').classList.remove('open');if(page==='library')renderLibrary();if(page==='models')renderModels();if(page==='workflows')renderSaved();if(page==='tutorial')window.renderSetupTutorial?.();history.replaceState(null,'','#'+page);}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));
$('open-library').onclick=()=>navigate('library');$('browse-models').onclick=()=>navigate('models');$('mobile-menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');
document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate('create');};
function setStyle(value){if(!['None','Cinematic','Photographic','Analog'].includes(value))throw Error('Choose a supported style.');state.style=value;document.querySelectorAll('[data-style]').forEach(b=>{b.classList.toggle('active',b.dataset.style===value);b.setAttribute('aria-pressed',String(b.dataset.style===value));const check=b.querySelector('.selected-check');if(check)check.remove();if(b.dataset.style===value&&value!=='None'){const span=document.createElement('span');span.className='selected-check';span.innerHTML=icon('check');b.querySelector('.style-thumb').append(span);}});updateNodes();}
function setRatio(value){if(!dimensions[value])throw Error('Choose a supported aspect ratio.');state.ratio=value;document.querySelectorAll('[data-ratio]').forEach(b=>{b.classList.toggle('active',b.dataset.ratio===value);b.setAttribute('aria-pressed',String(b.dataset.ratio===value));});$('dimensions-label').textContent=dimensions[value].join(' × ');updateNodes();}
document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>setStyle(b.dataset.style));document.querySelectorAll('[data-ratio]').forEach(b=>b.onclick=()=>setRatio(b.dataset.ratio));
function setMode(mode){state.mode=mode;document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-selected',String(b.dataset.mode===mode));});$('reference-field').hidden=mode!=='image';$('denoise-field').hidden=mode!=='image';document.querySelectorAll('[data-ratio]').forEach(b=>b.disabled=mode==='image');$('dimensions-label').textContent=mode==='image'?'From reference image':dimensions[state.ratio].join(' × ');updateNodes();}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
$('reference-upload').onchange=e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>20*1024*1024){toast('Choose a PNG, JPEG, or WebP smaller than 20 MB.');return;}if(state.reference?.url)URL.revokeObjectURL(state.reference.url);state.reference={file,url:URL.createObjectURL(file)};$('reference-preview').onload=()=>{if(state.reference){state.reference.width=$('reference-preview').naturalWidth;state.reference.height=$('reference-preview').naturalHeight;}};$('reference-preview').src=state.reference.url;$('reference-preview').hidden=false;$('reference-label').textContent=file.name;};
function changeBatch(amount){$('batch').value=Math.max(1,Math.min(4,Number($('batch').value)+amount));$('batch').dispatchEvent(new Event('change'));} $('batch-minus').onclick=()=>changeBatch(-1);$('batch-plus').onclick=()=>changeBatch(1);
for(const id of ['steps','cfg','denoise'])$(id).oninput=()=>{$(`${id}-value`).textContent=$(id).value;updateNodes();};
$('seed').oninput=updateNodes;$('sampler').onchange=updateNodes;$('model').onchange=()=>{const file=$('model').value;$('model-description').textContent=state.connected?file:'Example model · connect to use';window.onModelSelectionChange?.();updateNodes();};$('prompt').oninput=updateNodes;$('negative').oninput=updateNodes;
function randomSeed(){const n=crypto.getRandomValues(new Uint32Array(1))[0];$('seed').value=n;updateNodes();return n;}
$('random-seed').onclick=randomSeed;
const ideas=[defaultPrompt,'A quiet botanical greenhouse after the rain, soft morning light filtering through glass, lush foliage and climbing vines, cinematic photography, calm and inviting atmosphere.','A secluded modern cabin in a snowy mountain forest, glowing amber windows, blue hour, fresh snow, atmospheric cinematic photography, a sense of warmth and stillness.'];let ideaIndex=0;
$('prompt-idea').onclick=()=>{$('prompt').value=ideas[++ideaIndex%ideas.length];updateNodes();toast('A fresh starting point. Make it your own.');};
function readSettings(){return{prompt:$('prompt').value.trim(),negative:$('negative').value.trim(),model:$('model').value,style:state.style,ratio:state.ratio,batch:Number($('batch').value),steps:Number($('steps').value),cfg:Number($('cfg').value),seed:Number($('seed').value),sampler:$('sampler').value,denoise:Number($('denoise').value),mode:state.mode};}
function applySettings(settings){if(state.busy){toast('Wait for the current generation to finish.');return;}for(const key of ['prompt','negative','steps','cfg','seed','sampler','batch'])if(settings[key]!==undefined)$(key).value=settings[key];if(settings.model&&[...$('model').options].some(o=>o.value===settings.model)){$('model').value=settings.model;$('model').dispatchEvent(new Event('change'));}if(settings.style)setStyle(settings.style);if(settings.ratio)setRatio(settings.ratio);if(settings.mode)setMode(settings.mode);for(const id of ['steps','cfg','denoise'])$(`${id}-value`).textContent=$(id).value;updateNodes();}
function usePreset(key){const preset=presets[key];if(!preset)return;applySettings(preset);state.project=preset.title;$('project-title').textContent=state.project;navigate('create');toast(`${preset.title} is ready to make your own.`);}
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>usePreset(b.dataset.preset));
const workflowGrid=$('workflow-grid');for(const [key,preset] of Object.entries(presets)){const b=document.createElement('button');b.className='workflow-card';b.innerHTML=`<img src="${preset.image}" alt="Example artwork for this workflow"><div class="workflow-card-content"><h2>${preset.title}</h2><p>${preset.description}</p><small>${preset.tag}</small></div>`;b.onclick=()=>usePreset(key);workflowGrid.append(b);}
function blankWorkflow(){applySettings({prompt:'',negative:'',style:'None',ratio:'1:1',batch:1,steps:25,cfg:7,mode:'text'});state.project='Untitled workflow';$('project-title').textContent=state.project;navigate('create');$('prompt').focus();}
$('new-workflow').onclick=blankWorkflow;$('blank-workflow').onclick=blankWorkflow;
$('save-workflow').onclick=()=>{const settings=readSettings();const found=state.saved.find(s=>s.name===state.project);if(found)found.settings=settings;else state.saved.push({name:state.project,settings});toast('Workflow saved for this session.');renderSaved();};
function renderSaved(){const root=$('saved-list');root.replaceChildren();if(!state.saved.length){const p=document.createElement('p');p.className='empty-copy';p.textContent='Save your favorite settings from the studio to find them here.';root.append(p);return;}for(const item of state.saved){const b=document.createElement('button');b.className='saved-row';b.innerHTML=`<span>${icon('workflow')}</span><div><strong></strong><small></small></div><span>${icon('chevron')}</span>`;b.querySelector('strong').textContent=item.name;b.querySelector('small').textContent=`${item.settings.style} · ${item.settings.ratio} · ${item.settings.steps} steps`;b.onclick=()=>{applySettings(item.settings);state.project=item.name;$('project-title').textContent=item.name;navigate('create');toast('Saved settings restored.');};root.append(b);}}
$('rename-project').onclick=()=>{$('project-name').value=state.project;$('rename-dialog').showModal();};$('rename-form').onsubmit=e=>{e.preventDefault();const name=$('project-name').value.trim();if(!name)return;state.project=name;$('project-title').textContent=name;$('rename-dialog').close();};
function selectedImage(){return images.find(im=>im.id===state.selected)||images[0];}
function selectImage(id){const im=images.find(x=>x.id===id);if(!im)return;state.selected=id;$('main-image').src=im.src;$('main-image').alt=im.prompt;$('output-name').textContent='Your creation';$('output-model').textContent=im.model;$('output-size').textContent=im.size;$('output-style').textContent=im.style;$('output-badge').textContent=im.sample?'Sample':'Generated';$('output-time').textContent=im.sample?'Demo image':`${im.seconds}s · ${im.provider==='gemini'?'Gemini cloud':'Local'}`;$('node-result').src=im.src;updateFavoriteButton();renderGallery();}
function updateFavoriteButton(){const favorite=selectedImage().favorite;$('favorite-image').classList.toggle('favorited',favorite);$('favorite-image').setAttribute('aria-pressed',String(favorite));$('favorite-image').setAttribute('aria-label',favorite?'Remove from favorites':'Favorite image');}
function toggleFavorite(id){const im=images.find(x=>x.id===id);if(!im)return;im.favorite=!im.favorite;updateFavoriteButton();renderLibrary();toast(im.favorite?'Added to favorites for this session.':'Removed from favorites.');}
$('favorite-image').onclick=()=>toggleFavorite(state.selected);
function renderGallery(){const root=$('session-gallery');root.replaceChildren();images.slice(0,9).forEach(im=>{const b=document.createElement('button');b.className='gallery-item'+(im.id===state.selected?' selected':'');b.setAttribute('aria-label',`View ${im.name}${im.sample?' (sample)':''}`);b.setAttribute('aria-pressed',String(im.id===state.selected));b.innerHTML=`<div class="gallery-image"><img src="${im.src}" alt="" loading="lazy"></div><div class="gallery-meta"><span></span><span></span></div>`;b.querySelector('.gallery-meta span:first-child').textContent=im.name;b.querySelector('.gallery-meta span:last-child').textContent=im.sample?'Sample':im.style;b.onclick=()=>selectImage(im.id);root.append(b);});$('session-count').textContent=images.length;$('library-count').textContent=images.length;}
function renderLibrary(){const root=$('library-grid');root.replaceChildren();const visible=images.filter(im=>!state.favoritesOnly||im.favorite);if(!visible.length){const p=document.createElement('p');p.className='empty-copy';p.textContent='A place for your favorites. Tap a heart on an image to add it here.';p.style.gridColumn='1 / -1';root.append(p);}for(const im of visible){const card=document.createElement('article');card.className='library-card';card.innerHTML=`<button class="library-open" aria-label="View image"><img src="${im.src}" alt="" loading="lazy"></button><div class="library-caption"><div><strong></strong><small></small></div><button class="icon-button${im.favorite?' favorited':''}" aria-label="Toggle favorite">${icon('heart')}</button></div>`;card.querySelector('img').alt=im.prompt;card.querySelector('strong').textContent=im.name;card.querySelector('small').textContent=`${im.style} · ${im.sample?'Sample image':im.size}`;card.querySelector('.library-open').onclick=()=>{selectImage(im.id);navigate('create');};card.querySelector('.icon-button').onclick=()=>toggleFavorite(im.id);root.append(card);}}
function filterLibrary(favorite){state.favoritesOnly=favorite;$('all-images').classList.toggle('active',!favorite);$('favorite-filter').classList.toggle('active',favorite);renderLibrary();}
$('all-images').onclick=()=>filterLibrary(false);$('favorite-filter').onclick=()=>filterLibrary(true);
async function downloadImage(){const im=selectedImage();try{const response=await fetch(im.src);if(!response.ok)throw Error();const blob=await response.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`comfy-studio-${im.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}.${blob.type.includes('webp')?'webp':'png'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}catch{toast('Could not download. Reconnect your server and try again.');}}
$('download-image').onclick=downloadImage;$('expand-image').onclick=()=>{$('full-image').src=selectedImage().src;$('full-image').alt=selectedImage().prompt;$('image-dialog').showModal();};
function setView(nodes){state.nodeView=nodes;$('studio-view').classList.toggle('active',!nodes);$('nodes-view').classList.toggle('active',nodes);$('studio-view').setAttribute('aria-pressed',String(!nodes));$('nodes-view').setAttribute('aria-pressed',String(nodes));document.querySelector('.output-panel').hidden=nodes;$('node-panel').hidden=!nodes;updateNodes();}
$('studio-view').onclick=()=>setView(false);$('nodes-view').onclick=()=>setView(true);
function updateNodes(){const s=readSettings();$('node-model').textContent=$('model').selectedOptions[0]?.text||s.model;$('node-prompt').textContent=s.prompt.slice(0,165)+(s.prompt.length>165?'…':'');$('node-settings').textContent=`${s.steps} steps · guidance ${s.cfg}\n${dimensions[s.ratio].join(' × ')} · ${s.sampler}\nSeed ${s.seed}`;$('node-settings').style.whiteSpace='pre-line';}
function effectivePrompt(s){const styles={None:'',Cinematic:', cinematic lighting, rich depth, atmospheric composition',Photographic:', natural photography, realistic detail, high quality',Analog:', 35mm film photography, subtle grain, warm tones'};return s.prompt+styles[s.style];}
function buildWorkflow(s,referenceName){const [width,height]=dimensions[s.ratio];const nodes={
 '1':{class_type:'CheckpointLoaderSimple',inputs:{ckpt_name:s.model}},
 '2':{class_type:'CLIPTextEncode',inputs:{text:effectivePrompt(s),clip:['1',1]}},
 '3':{class_type:'CLIPTextEncode',inputs:{text:s.negative,clip:['1',1]}},
 '4':{class_type:'EmptyLatentImage',inputs:{width,height,batch_size:s.batch}},
 '5':{class_type:'KSampler',inputs:{model:['1',0],positive:['2',0],negative:['3',0],latent_image:['4',0],seed:s.seed,steps:s.steps,cfg:s.cfg,sampler_name:s.sampler,scheduler:'normal',denoise:s.mode==='image'?s.denoise:1}},
 '6':{class_type:'VAEDecode',inputs:{samples:['5',0],vae:['1',2]}},
 '7':{class_type:'SaveImage',inputs:{images:['6',0],filename_prefix:'ComfyStudio'}}};
 if(s.mode==='image'&&referenceName){nodes['4']={class_type:'VAEEncode',inputs:{pixels:['8',0],vae:['1',2]}};nodes['8']={class_type:'LoadImage',inputs:{image:referenceName}};if(s.batch>1){nodes['9']={class_type:'RepeatLatentBatch',inputs:{samples:['4',0],amount:s.batch}};nodes['5'].inputs.latent_image=['9',0];}}
 return nodes;
}
$('export-nodes').onclick=()=>{const s=readSettings();if(s.mode==='image'){toast('JSON export currently supports text-to-image workflows.');return;}const blob=new Blob([JSON.stringify(buildWorkflow(s),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='comfy-studio-api-workflow.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('ComfyUI API workflow exported.');};
const exampleModels=[{file:'sd_xl_base_1.0.safetensors',name:'Stable Diffusion XL',desc:'A versatile starting point for detailed, expressive images.',size:'SDXL · Example model'},{file:'DreamShaperXL1.0Alpha2_fixedVae_half_00001_.safetensors',name:'DreamShaper XL',desc:'A creative checkpoint for illustrative and cinematic looks.',size:'SDXL · Example model'},{file:'v1-5-pruned-emaonly.safetensors',name:'Stable Diffusion 1.5',desc:'A lighter model for quick experiments and smaller GPUs.',size:'SD 1.5 · Example model'}];
