function openConnection(){$('connection-error').hidden=true;$('connection-dialog').showModal();}
$('connect-sidebar').onclick=openConnection;$('settings-button').onclick=openConnection;document.querySelectorAll('.connect-trigger').forEach(b=>b.onclick=openConnection);$('help-button').onclick=()=>$('help-dialog').showModal();
function updateConnectionUI(){$('connection-label').textContent=state.connected?'Server connected':'Connect local server';$('mode-badge').innerHTML=icon(state.connected?'monitor':'flask')+(state.connected?'Local server connected':'Demo workspace');$('footer-connection').textContent=state.connected?'Connected · '+new URL(state.server).host:'Demo mode · no server connected';$('generate-note').innerHTML=icon(state.connected?'shield':'flask')+(state.connected?'Generated on your connected server':'Sample preview · connect for local generation');$('disconnect-server').hidden=!state.connected;$('model-description').textContent=state.connected?$('model').value:'SDXL 1.0 · Example model';$('cancel-generation').textContent=state.connected?'Stop waiting':'Cancel';window.onServerStateChange?.();renderModels();}
async function connectToServer(url,silent=false){if(state.busy){if(!silent)toast('Finish the current generation before changing servers.');return false;}const button=$('connect-submit');if(button&&!silent){button.disabled=true;button.textContent='Connecting…';}$('connection-error').hidden=true;try{const parsed=new URL(url||$('server-url').value);if(!['http:','https:'].includes(parsed.protocol)||parsed.username||parsed.password)throw Error('Use an HTTP or HTTPS address without a password.');const server=parsed.origin+parsed.pathname.replace(/\/$/,'');const timeout=AbortSignal.timeout(10000);const response=await fetch(server+'/object_info/CheckpointLoaderSimple',{signal:timeout});if(!response.ok)throw Error(`ComfyUI returned ${response.status}. Check the server address.`);const info=await response.json();const models=info.CheckpointLoaderSimple?.input?.required?.ckpt_name?.[0];if(!Array.isArray(models))throw Error('This address did not return a ComfyUI checkpoint list. Check the server address.');state.server=server;state.models=models;state.connected=true;if($('server-url'))$('server-url').value=server;$('model').replaceChildren();for(const name of models){const option=document.createElement('option');option.value=name;option.textContent=name;$('model').append(option);}updateConnectionUI();updateNodes();$('connection-dialog').close();toast(models.length?'Connected to ComfyUI ('+models.length+' checkpoints found).':'Server connected. Add a checkpoint, then refresh Models.');return true;}catch(err){if(!silent){$('connection-error').textContent=err.message.includes('fetch')||err.name==='TimeoutError'?'Could not reach ComfyUI. Check that it is running, allows this page’s origin, and your browser permits local network access.':err.message;$('connection-error').hidden=false;}return false;}finally{if(button&&!silent){button.disabled=false;button.textContent='Connect server';}}}
$('connection-form').onsubmit=async e=>{e.preventDefault();await connectToServer($('server-url').value,false);};
$('disconnect-server').onclick=()=>{if(state.busy){toast('Finish the current generation before disconnecting.');return;}state.connected=false;state.server=null;state.models=[];$('model').replaceChildren();for(const m of exampleModels){const o=document.createElement('option');o.value=m.file;o.textContent=m.name;$('model').append(o);}updateConnectionUI();updateNodes();$('connection-dialog').close();toast('Disconnected. Back to sample previews.');};
function wait(ms,signal){return new Promise((resolve,reject)=>{const timer=setTimeout(done,ms);function done(){signal?.removeEventListener('abort',abort);resolve();}function abort(){clearTimeout(timer);signal?.removeEventListener('abort',abort);reject(new DOMException('Stopped','AbortError'));}if(signal?.aborted)abort();else signal?.addEventListener('abort',abort,{once:true});});}
function setBusy(busy){state.busy=busy;$('generate-button').disabled=busy;$('generate-label').textContent=busy?'Creating…':Number($('batch').value)>1?'Generate images':'Generate image';$('generating-overlay').hidden=!busy;$('footer-status').innerHTML=icon(busy?'flask':'check-circle')+(busy?(state.connected?'Generating locally':'Previewing samples'):'Ready when you are');for(const el of document.querySelectorAll('#generate-form input,#generate-form select,#generate-form textarea,#generate-form button[type="button"]'))el.disabled=busy;document.querySelectorAll('[data-ratio]').forEach(b=>b.disabled=busy||state.mode==='image');window.updateGuideGenerationState?.();}
$('batch').addEventListener('change',()=>{$('generate-label').textContent=Number($('batch').value)>1?'Generate images':'Generate image';});
async function localGeneration(s,signal){let referenceName;if(s.mode==='image'){const form=new FormData();form.append('image',state.reference.file);form.append('overwrite','false');const response=await fetch(state.server+'/upload/image',{method:'POST',body:form,signal});if(!response.ok)throw Error('The reference image could not be uploaded.');const result=await response.json();referenceName=(result.subfolder?result.subfolder+'/':'')+result.name;}
 const response=await fetch(state.server+'/prompt',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:buildWorkflow(s,referenceName),client_id:crypto.randomUUID()}),signal});const result=await response.json();if(!response.ok||result.error)throw Error(result.error?.message||'This model could not run the standard checkpoint workflow. Choose an SD or SDXL checkpoint.');if(!result.prompt_id)throw Error('The server did not return a generation ID.');activePromptId=result.prompt_id;$('progress-title').textContent='Creating on your machine';$('progress-description').textContent='Your job is queued. ComfyUI will handle the rest.';const start=Date.now();while(Date.now()-start<300000){await wait(1200,signal);const historyResponse=await fetch(state.server+'/history/'+encodeURIComponent(activePromptId),{signal});if(!historyResponse.ok)throw Error('Lost contact with ComfyUI. Your job may still be running.');const history=await historyResponse.json();const job=history[activePromptId];if(job?.status?.status_str==='error'){const error=job.status.messages?.find(m=>m[0]==='execution_error')?.[1];throw Error(error?.exception_message||'ComfyUI could not complete this image. Check the model and available memory.');}const outputs=job?.outputs;if(outputs){const outputImages=Object.values(outputs).flatMap(o=>o.images||[]);if(outputImages.length)return outputImages.map((image,i)=>({id:crypto.randomUUID(),src:state.server+'/view?'+new URLSearchParams({filename:image.filename,subfolder:image.subfolder||'',type:image.type||'output'}),name:`Creation ${images.filter(im=>!im.sample).length+i+1}`,prompt:s.prompt,style:s.style,model:$('model').selectedOptions[0].text,size:s.mode==='image'&&state.reference.width?[Math.floor(state.reference.width/8)*8,Math.floor(state.reference.height/8)*8].join(' × '):dimensions[s.ratio].join(' × '),seed:s.seed,sample:false,favorite:false,seconds:Math.round((Date.now()-start)/1000)}));if(job.status?.completed)throw Error('The workflow finished without an image. Check ComfyUI’s output.');}$('progress-description').textContent=`Waiting for ComfyUI · ${Math.round((Date.now()-start)/1000)} seconds`;}
 throw Error('Still waiting after five minutes. Your job may finish in ComfyUI; check its queue.');}
async function generate(){if(state.busy)return;if(window.geminiProviderActive?.())return window.generateGemini();if(window.isThreeMode?.())return window.generateThree();const s=readSettings();if(state.connected&&(!s.model||window.classifyInstalledModel?.(s.model)?.compatible===false)){navigate('models');toast('Choose a compatible installed checkpoint first.');return;}if(!s.prompt){$('prompt').focus();toast('Give your idea a few words first.');return;}if(!Number.isInteger(s.seed)||s.seed<0||s.seed>4294967295){$('advanced').open=true;$('seed').focus();toast('Choose a seed between 0 and 4,294,967,295.');return;}if(s.mode==='image'&&!state.reference){toast('Choose a reference image first.');return;}if(s.mode==='image'&&!state.connected){openConnection();toast('Connect your server to transform a reference image.');return;}setView(false);generationController=new AbortController();activePromptId=null;setBusy(true);try{if(state.connected){$('progress-title').textContent='Preparing your workflow';$('progress-description').textContent='Sending your prompt to your local server.';const results=await localGeneration(s,generationController.signal);images.unshift(...results);selectImage(results[0].id);toast(`${results.length===1?'Your image is':results.length+' images are'} ready.`);}else{$('progress-title').textContent='Previewing the creation flow';$('progress-description').textContent='Demo mode uses sample artwork, independent of your prompt.';await wait(1500,generationController.signal);const samples=images.filter(im=>im.sample);const result=samples.find(im=>im.style===s.style)||samples[0];selectImage(result.id);toast('Sample preview complete. Connect ComfyUI to generate your prompt.');}}catch(err){if(err.name==='AbortError')toast(state.connected?'Stopped waiting. A running server job may still finish.':'Preview canceled.');else toast(err.message);}finally{setBusy(false);activePromptId=null;}}
$('generate-form').onsubmit=e=>{e.preventDefault();generate();};
$('cancel-generation').onclick=async()=>{generationController?.abort();if(state.connected&&activePromptId){try{await fetch(state.server+'/queue',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({delete:[activePromptId]}),signal:AbortSignal.timeout(4000)});}catch{/* Stop waiting never interrupts other server users. */}}};
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&!document.querySelector('dialog[open]')){e.preventDefault();navigate('create');generate();}if((e.metaKey||e.ctrlKey)&&e.key==='1'){e.preventDefault();navigate('create');}if(e.key==='Escape')document.querySelector('.sidebar').classList.remove('open');});
if(document.modelContext?.registerTool){const life=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:life.signal})).catch(()=>{});}catch{}};register({name:'get_creation_settings',description:'Read the current visible Comfy Studio image settings and connection state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({...readSettings(),connected:state.connected,busy:state.busy})});register({name:'set_creation_settings',description:'Configure the visible image prompt, style, and aspect ratio. Does not generate an image or connect a server.',inputSchema:{type:'object',properties:{prompt:{type:'string',minLength:1,maxLength:5000},style:{type:'string',enum:['None','Cinematic','Photographic','Analog']},ratio:{type:'string',enum:['1:1','4:3','3:4','16:9']}},required:['prompt'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(state.busy)throw Error('A generation is currently running.');if(!input||typeof input.prompt!=='string'||!input.prompt.trim()||input.prompt.length>5000)throw Error('A prompt of 1–5000 characters is required.');if(input.style&&!['None','Cinematic','Photographic','Analog'].includes(input.style))throw Error('Unsupported style.');if(input.ratio&&!dimensions[input.ratio])throw Error('Unsupported ratio.');applySettings(input);navigate('create');return readSettings();}});window.addEventListener('pagehide',()=>life.abort(),{once:true});}
setStyle(state.style);setRatio(state.ratio);renderGallery();renderLibrary();renderSaved();renderModels();updateNodes();navigate(location.hash.slice(1)||'create');
(async()=>{const p=new URLSearchParams(location.search);const target=p.get('server')||'http://127.0.0.1:8188';if(p.get('autoconnect')!=='false'){for(let i=0;i<30&&!state.connected;i++){const ok=await connectToServer(target,true);if(ok)break;await wait(2000);}}})();
